package net.officefloor.hq.app.rate;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the rate form from the body; refuses a grade other than A, B or C and a percent that is missing, negative or has more than two decimals,
 * a from-date or to-date that is not a calendar date, and a to-date before the from-date. A blank from-date means from the beginning of time. */
public class ValidateRate {

    public void validate(@RequestBody RateRequest request, Out<RateInput> body) throws InvalidRateException {
        body.set(RateRules.check(request));
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Sets the grade's rate from the from-date on the sheet, replacing the one it had for that from-date, and logs it
 *  with the sheet's today (so the rates can be worked out as they stood on an earlier date). */
public class ApplyRate {
    public void apply(@Val RateInput input, @Val Sheet sheet, RateRepository repository, RateLogRepository log,
            Out<Rate> rateOut) {
        rateOut.set(RateRules.set(input, sheet, repository, log));
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.Sheet;

/** The rate form's rules and how it sets a rate, shared by the form and the rate import. */
public final class RateRules {

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    private static final Pattern PCT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    private RateRules() {
    }

    /** Checks a rate as the rate form does, returning it validated. */
    public static RateInput check(RateRequest request) throws InvalidRateException {
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        String pct = request == null || request.pct() == null ? "" : request.pct().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidRateException("The grade must be A, B or C.");
        }
        if (!PCT.matcher(pct).matches()) {
            throw new InvalidRateException("The rate must be a percent, 0.00 or more, with up to two decimals.");
        }
        String from = request == null || request.from() == null ? "" : request.from().trim();
        LocalDate parsed = null;
        if (!from.isEmpty()) {
            try {
                parsed = LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidRateException("The from-date must be a calendar date.");
            }
        }
        String to = request == null || request.to() == null ? "" : request.to().trim();
        LocalDate until = null;
        if (!to.isEmpty()) {
            try {
                until = LocalDate.parse(to);
            } catch (DateTimeParseException e) {
                throw new InvalidRateException("The to-date must be a calendar date.");
            }
        }
        if (parsed != null && until != null && until.isBefore(parsed)) {
            throw new InvalidRateException("The to-date must not be before the from-date.");
        }
        return new RateInput(grade, new BigDecimal(pct).setScale(2), parsed, until);
    }

    /** Sets the grade's rate as the rate form does, returning it saved. */
    public static Rate set(RateInput input, Sheet sheet, RateRepository repository, RateLogRepository log) {
        Rate rate = repository.findWithFrom(sheet.getId(), input.grade(), input.from())
                .orElseGet(() -> new Rate(sheet.getId(), input.grade(), input.pct(), input.from(), input.to()));
        rate.setPct(input.pct());
        rate.setToDate(input.to());
        Rate saved = repository.saveAndFlush(rate);
        log.saveAndFlush(new RateLog(saved, sheet.getToday()));
        return saved;
    }
}
package net.officefloor.hq.app.importrates;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRules;
import net.officefloor.hq.app.rate.AuditRateSet;
import net.officefloor.hq.app.rate.RateInput;
import net.officefloor.hq.app.rate.RateLogRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/**
 * Sets the checked lines in order, each exactly as the rate form would: replacing the grade's rate for the same
 * from-date, recorded as RATE_SET, followed by the figures it moved.
 */
public class SetImportedRates {
    public void set(@Val ImportedRates lines, @Val Sheet sheet, RateRepository rates, RateLogRepository log,
            SheetRepository sheets, PersonRepository people, ClaimRepository claims, PersonGradeRepository grades,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit, Out<RatesSet> setOut) {
        AuditRateSet auditRate = new AuditRateSet();
        String by = AuditUser.decode(user);
        for (RateInput line : lines.rates()) {
            Rollup before = Rollup.of(sheet.getId(), sheets, people, claims, rates, grades);
            auditRate.audit(RateRules.set(line, sheet, rates, log), user, audit);
            Rollup.of(sheet.getId(), sheets, people, claims, rates, grades).changesSince(before, sheet.getId(), by)
                    .forEach(audit::record);
        }
        setOut.set(new RatesSet(lines.rates().size()));
    }
}

